#!/usr/bin/env python3
"""Execute public fixtures as real, bounded, nonprivileged child invocations."""
import argparse
import json
import os
from pathlib import Path
import shutil
import signal
import stat
import sys
import uuid

HERE=Path(__file__).resolve().parent
from public_process import invoke, CandidateFailure, InfrastructureError
from protocol import loads
from certify import compare, public_load_relation
from bootstrap import prepare


def freeze_tree(source,target):
    """Freeze arbitrary auxiliary regular files within the published tree bounds."""
    source=Path(source)
    if source.is_symlink() or not source.is_dir() or not (source/'main.py').is_file():
        raise CandidateFailure('expected submission directory with main.py')
    total=entries=files=0
    for base,dirs,names in os.walk(source,followlinks=False):
        parent=Path(base);relative=parent.relative_to(source)
        for name in dirs+names:
            path=parent/name;st=path.lstat();entries+=1
            if entries>512 or not (stat.S_ISREG(st.st_mode) or stat.S_ISDIR(st.st_mode)):
                raise CandidateFailure('unsafe tree or more than512 entries')
            dest=target/relative/name
            if stat.S_ISDIR(st.st_mode):dest.mkdir();continue
            files+=1;total+=st.st_size
            if files>128 or st.st_nlink!=1 or st.st_size>256*1024 or total>2*1024*1024:
                raise CandidateFailure('submission file/link/byte bound exceeded')
            fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
            try:
                before=os.fstat(fd)
                with os.fdopen(fd,'rb',closefd=False) as stream:data=stream.read(256*1024+1)
                after=os.fstat(fd)
                fields=lambda v:(v.st_dev,v.st_ino,v.st_size,v.st_mtime_ns,v.st_ctime_ns)
                if fields(st)!=fields(before) or fields(before)!=fields(after) or len(data)!=st.st_size:
                    raise InfrastructureError('submission changed during freeze')
                dest.write_bytes(data)
            finally:os.close(fd)


def interrupted(signum,frame):
    # Repeated TERM/INT cannot interrupt cleanup after the first signal.
    signal.signal(signal.SIGTERM,signal.SIG_IGN)
    signal.signal(signal.SIGINT,signal.SIG_IGN)
    raise InfrastructureError('public checker interrupted')


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('candidate',type=Path)
    parser.add_argument('--runtime',type=Path,help='legacy option; public check uses the current Python runtime')
    parser.add_argument('--work-base',type=Path,default=HERE/'.public-check')
    parser.add_argument('--fixtures',type=Path,default=HERE/'examples.json')
    args=parser.parse_args()
    if os.getuid()==0 or os.geteuid()==0:
        raise InfrastructureError('public check must run as an ordinary nonroot user')
    args.work_base.mkdir(mode=0o700,parents=True,exist_ok=True)
    st=args.work_base.lstat()
    if not stat.S_ISDIR(st.st_mode) or st.st_uid!=os.geteuid() or st.st_mode&0o077:
        raise InfrastructureError('unsafe work-base directory')
    run=args.work_base.resolve()/uuid.uuid4().hex
    run.mkdir(mode=0o700)
    try:
        stage=run/'stage'; stage.mkdir()
        freeze_tree(args.candidate,stage)
        dependency=prepare()
        fixtures=json.loads(args.fixtures.read_text())
        worker=HERE/'check_worker'
        # Trusted infrastructure probe precedes submitted code. Candidate text
        # and exit status never claim an authoritative infrastructure diagnosis.
        probe=invoke(worker,[sys.executable,'-B','-c',
                     'import os,resource,sys; assert os.getuid()!=0; '
                     'assert sys.version_info[:2]==(3,11); '
                     'assert resource.getrlimit(resource.RLIMIT_AS)==(2147483648,2147483648); '
                     'assert resource.getrlimit(resource.RLIMIT_CPU)==(120,121); '
                     'assert resource.getrlimit(resource.RLIMIT_NOFILE)==(64,64); '
                     'assert resource.getrlimit(resource.RLIMIT_FSIZE)==(16777216,16777216); '
                     'import numpy; assert numpy.__version__=="1.26.4"; '
                     'print("ordinary-public-worker-ready")'],b'',run/'probe-tmp',timeout=10,pythonpath=dependency)
        if probe.returncode!=0 or probe.stdout!=b'ordinary-public-worker-ready\n' or probe.stderr:
            raise InfrastructureError('ordinary public worker preflight failed')
        timing=[]
        for i,fixture in enumerate(fixtures):
            raw=fixture.get('raw')
            if raw is None:
                raw=json.dumps(fixture['request'],separators=(',',':'))
            data=raw.encode('utf-8')
            result=invoke(worker,[sys.executable,'-B',str(stage/'main.py')],data,run/('tmp-'+str(i)),pythonpath=dependency)
            if result.returncode!=0:
                raise CandidateFailure('nonzero candidate exit: '+str(result.returncode))
            try:
                response=loads(result.stdout)
                compare(response,fixture['expected'])
                public_load_relation(response)
            except (ValueError,OverflowError,RecursionError) as exc:
                raise CandidateFailure('output rejected: '+str(exc)) from exc
            timing.append({'name':fixture['name'],'seconds':round(result.seconds,6)})
    finally:
        shutil.rmtree(run)
    # Commit only after child cleanup AND removal of all ephemeral staged bytes.
    # Keep TERM/INT blocked through process exit after this publication point.
    signal.pthread_sigmask(signal.SIG_BLOCK,{signal.SIGTERM,signal.SIGINT})
    if signal.sigpending() & {signal.SIGTERM,signal.SIGINT}:
        raise InfrastructureError('interrupted before success publication')
    print(json.dumps({'status':'pass','fixtures':len(fixtures),'timings':timing}),flush=True)


if __name__=='__main__':
    signal.signal(signal.SIGTERM,interrupted)
    signal.signal(signal.SIGINT,interrupted)
    try:
        main()
    except CandidateFailure as exc:
        print(json.dumps({'status':'candidate_failure','detail':str(exc)}))
        sys.exit(1)
    except (InfrastructureError,OSError) as exc:
        print(json.dumps({'status':'infrastructure_error','detail':str(exc)}))
        sys.exit(2)
