#define DENY(n) BPF_JUMP(BPF_JMP|BPF_JEQ|BPF_K,(n),0,1), BPF_STMT(BPF_RET|BPF_K,SECCOMP_RET_ERRNO|EPERM)
int main(int argc, char **argv) {
    if (argc < 2 || getuid() == 0 || geteuid() == 0) {
        fputs("ordinary nonroot execution required\n", stderr);
        return 126;
    }
    struct rlimit mem={2UL*1024*1024*1024,2UL*1024*1024*1024}, cpu={120,121};
    struct rlimit file={16UL*1024*1024,16UL*1024*1024}, fds={64,64}, proc={64,64}, core={0,0};
    if (setrlimit(RLIMIT_AS,&mem)||setrlimit(RLIMIT_CPU,&cpu)||setrlimit(RLIMIT_FSIZE,&file)||
        setrlimit(RLIMIT_NOFILE,&fds)||setrlimit(RLIMIT_NPROC,&proc)||setrlimit(RLIMIT_CORE,&core)) {perror("rlimit");return 3;}
    sigset_t empty;
    sigemptyset(&empty);
    if (sigprocmask(SIG_SETMASK, &empty, NULL)) {perror("signal mask");return 3;}
    struct sock_filter filter[]={
        BPF_STMT(BPF_LD|BPF_W|BPF_ABS,offsetof(struct seccomp_data,arch)),
        BPF_JUMP(BPF_JMP|BPF_JEQ|BPF_K,AUDIT_ARCH_X86_64,1,0),
        BPF_STMT(BPF_RET|BPF_K,SECCOMP_RET_KILL_PROCESS),
        BPF_STMT(BPF_LD|BPF_W|BPF_ABS,offsetof(struct seccomp_data,nr)),
        BPF_JUMP(BPF_JMP|BPF_JGE|BPF_K,0x40000000,0,1),
        BPF_STMT(BPF_RET|BPF_K,SECCOMP_RET_KILL_PROCESS),
        DENY(__NR_socket),DENY(__NR_socketpair),DENY(__NR_connect),
        DENY(__NR_shmget),DENY(__NR_shmat),DENY(__NR_shmctl),
        DENY(__NR_semget),DENY(__NR_semop),DENY(__NR_semctl),DENY(__NR_semtimedop),
        DENY(__NR_msgget),DENY(__NR_msgsnd),DENY(__NR_msgrcv),DENY(__NR_msgctl),
