"""One-domain CPU controller backend; normalized capacities, no external LP runtime.

The controller problem of PROTOCOL.md is the box-constrained convex program

    route:  minimise h + 0.5*rho*sum_live (z[e]-V[e])**2   s.t. h >= 0, z[e] <= h
    admit:  minimise      0.5*rho*sum_live (z[e]-V[e])**2   s.t. h  = 1, z[e] <= 1

`z` has no lower bound, so for a fixed ceiling the minimizer is `z=min(V,h)` and
the remaining one-dimensional problem is the monotone water-filling equation
`rho*sum_live max(V-h,0) = 1`, solved in closed form by sorting.
"""
from __future__ import annotations

import numpy as np


class PDLPMLU:

    def __init__(self, num_edges, rho, mode):
        self._num_edges = num_edges
        self._num_domains = 1
        self._objective = mode
        self._NUM_VARIABLES = num_edges + 1
        self._NUM_CONSTRAINTS = num_edges
        self.rho = float(rho)
        self.alpha = 1.0
        self._solved = False
        self._current_F = np.zeros(num_edges)
        self.active = np.ones(num_edges, dtype=bool)
        self._solution = np.zeros(self._NUM_VARIABLES)
        self._pressure_vector = np.zeros(num_edges)

    @property
    def num_edges(self):
        return self._num_edges

    @property
    def num_domains(self):
        return self._num_domains

    @property
    def is_mlu(self):
        return self._objective == 'route'

    def set_mode(self, mode):
        self._objective = mode
        self._solved = False

    def _get_variable_lower_bound_vector(self):
        out = np.full((self._NUM_VARIABLES,), -np.inf)
        if self.is_mlu:
            out[-1] = 0.0
        else:
            out[-1] = 1.0
        return out

    def _get_variable_upper_bound_vector(self):
        out = np.full((self._NUM_VARIABLES,), np.inf)
        out[:-1] = self.alpha  # z[e] <= h (route) / z[e] <= 1 (admit)
        if not self.is_mlu:
            out[-1] = 1.0
        return out

    def _get_objective_matrix_diagonal(self):
        d = np.full((self._NUM_VARIABLES,), fill_value=float(self.rho))
        d[-1] = 0.0
        return d

    def _get_objective_vector(self):
        out = np.zeros((self._NUM_VARIABLES,))
        out[:-1] = -self._current_F * self.rho
        if self.is_mlu:
            out[-1] = self.alpha * self.num_domains
        return out

    def update_F_m(self, new_F, rho=None):
        if rho is not None:
            self.rho = float(rho)
        self._current_F = np.array(new_F, dtype=np.float64).flatten()
        self._solved = False

    # ------------------------------------------------------------- solving
    def _ceiling(self, values: np.ndarray) -> float:
        """Smallest h>=0 with rho*sum max(v-h,0) <= 1, complementarily tight."""
        rho = float(self.rho)
        if values.size == 0:
            return 0.0
        positive = float(np.sum(np.maximum(values, 0.0)))
        if rho * positive <= 1.0:
            return 0.0
        ordered = np.sort(values)[::-1]
        cumulative = np.cumsum(ordered)
        count = ordered.size
        scale = max(1.0, rho * float(np.sum(np.abs(ordered))))
        for j in range(1, count + 1):
            candidate = (rho * float(cumulative[j - 1]) - 1.0) / (rho * j)
            if candidate <= 0.0:
                continue
            if j < count and candidate < float(ordered[j]):
                continue
            residual = rho * float(np.sum(np.maximum(ordered - candidate, 0.0))) - 1.0
            if abs(residual) <= 1e-10 * scale:
                return float(candidate)
        low, high = 0.0, float(ordered[0]) + 1.0 / rho
        for _ in range(200):
            middle = 0.5 * (low + high)
            if rho * float(np.sum(np.maximum(ordered - middle, 0.0))) > 1.0:
                low = middle
            else:
                high = middle
        return 0.5 * (low + high)

    def solve(self):
        target = self._current_F
        live = np.asarray(self.active, dtype=bool)
        z = np.zeros(self._num_edges, dtype=np.float64)
        pressure = np.zeros(self._num_edges, dtype=np.float64)
        if self.is_mlu:
            ceiling = self._ceiling(target[live])
        else:
            ceiling = 1.0
        for e in range(self._num_edges):
            if not live[e]:
                continue
            value = min(float(target[e]), ceiling)
            z[e] = value
            pressure[e] = float(self.rho) * (float(target[e]) - value)
            if pressure[e] < 0.0:
                pressure[e] = 0.0
        self._solution = np.concatenate([z, np.array([ceiling], dtype=np.float64)])
        self._pressure_vector = pressure
        self._solved = True
        return self

    @property
    def current_u(self):
        return float(self._solution[-1])

    @property
    def current_Z(self):
        return self._solution[:-1]

    @property
    def current_pressure(self):
        return self._pressure_vector

    @property
    def current_t_sum(self):
        return float(np.sum(self._pressure_vector[self.active]))
